#include <chrono>
#include <cstdint>
#include <memory>

#include <rclcpp/rclcpp.hpp>
#include <std_msgs/msg/int64.hpp>

namespace bench_nodes {

// Publishes a counter on "heartbeat" ten times a second, on the node's clock.
class Heartbeat : public rclcpp::Node {
 public:
  explicit Heartbeat(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("heartbeat", options) {
    publisher_ = create_publisher<std_msgs::msg::Int64>("heartbeat", rclcpp::QoS(rclcpp::KeepLast(10)));
    timer_ = create_timer(std::chrono::milliseconds(100), [this] {
      std_msgs::msg::Int64 msg;
      msg.data = next_++;
      publisher_->publish(msg);
    });
  }

 private:
  rclcpp::Publisher<std_msgs::msg::Int64>::SharedPtr publisher_;
  rclcpp::TimerBase::SharedPtr timer_;
  std::int64_t next_ = 0;
};

}  // namespace bench_nodes

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<bench_nodes::Heartbeat>());
  rclcpp::shutdown();
}

#include <cinttypes>
#include <cstdint>
#include <memory>
#include <optional>
#include <utility>
#include <variant>

#include <rclcpp/rclcpp.hpp>
#include <std_msgs/msg/int64.hpp>

namespace bench_nodes {

// What one heartbeat says about the stream.
struct InOrder {};
struct Gap {
  std::int64_t lost;  // heartbeats missing before this one
};
struct Restart {};
using Arrival = std::variant<InOrder, Gap, Restart>;

// The monitor's rules, in a plain class that a test reaches without ROS.
class HeartbeatCheck {
 public:
  [[nodiscard]] Arrival observe(std::int64_t value) {
    ++received_;
    const std::optional<std::int64_t> last = std::exchange(last_, value);
    if (!last || value == *last + 1) return InOrder{};
    if (value <= *last) return Restart{};
    return Gap{.lost = value - *last - 1};
  }

  [[nodiscard]] std::int64_t received() const { return received_; }

 private:
  std::optional<std::int64_t> last_;
  std::int64_t received_ = 0;
};

// Feeds each heartbeat to the check and logs what it finds.
class Monitor : public rclcpp::Node {
 public:
  explicit Monitor(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("monitor", options) {
    subscription_ = create_subscription<std_msgs::msg::Int64>(
        "heartbeat", rclcpp::QoS(rclcpp::KeepLast(10)),
        [this](const std_msgs::msg::Int64& msg) { on_heartbeat(msg.data); });
  }

  [[nodiscard]] std::int64_t received() const { return check_.received(); }

 private:
  void on_heartbeat(std::int64_t value) {
    const Arrival arrival = check_.observe(value);
    if (const auto* gap = std::get_if<Gap>(&arrival)) {
      RCLCPP_WARN(get_logger(), "lost %" PRId64 " heartbeats before %" PRId64, gap->lost, value);
    } else if (std::holds_alternative<Restart>(arrival)) {
      RCLCPP_INFO(get_logger(), "heartbeat restarted at %" PRId64, value);
    }
  }

  HeartbeatCheck check_;
  rclcpp::Subscription<std_msgs::msg::Int64>::SharedPtr subscription_;
};

}  // namespace bench_nodes

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<bench_nodes::Monitor>());
  rclcpp::shutdown();
}

#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <string>
#include <utility>
#include <variant>

namespace bench_nodes {

// What one heartbeat says about the stream.
struct InOrder {};
struct Gap {
  std::int64_t lost;  // heartbeats missing before this one
};
struct Restart {};
using Arrival = std::variant<InOrder, Gap, Restart>;

// The monitor's rules, without ROS.
class HeartbeatCheck {
 public:
  [[nodiscard]] Arrival observe(std::int64_t value) {
    ++received_;
    const std::optional<std::int64_t> last = std::exchange(last_, value);
    if (!last || value == *last + 1) return InOrder{};
    if (value <= *last) return Restart{};
    return Gap{.lost = value - *last - 1};
  }

  [[nodiscard]] std::int64_t received() const { return received_; }

 private:
  std::optional<std::int64_t> last_;
  std::int64_t received_ = 0;
};

}  // namespace bench_nodes

// One call operator per alternative; std::visit calls the one that matches.
struct Describe {
  std::string operator()(bench_nodes::InOrder) const { return "in order"; }
  std::string operator()(bench_nodes::Gap gap) const { return std::format("gap, {} lost", gap.lost); }
  std::string operator()(bench_nodes::Restart) const { return "restart"; }
};

int main() {
  bench_nodes::HeartbeatCheck check;
  for (const std::int64_t value : {3, 4, 7, 8, 0, 1}) {
    std::cout << std::format("{}: {}\n", value, std::visit(Describe{}, check.observe(value)));
  }
  std::cout << std::format("received {}\n", check.received());
}

#include <memory>

#include <rclcpp/rclcpp.hpp>

#include "bench_nodes/heartbeat.hpp"

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<bench_nodes::Heartbeat>());
  rclcpp::shutdown();
}

#include <variant>

#include <gtest/gtest.h>

#include "bench_nodes/heartbeat_check.hpp"

TEST(HeartbeatCheck, CountsTheHeartbeatsLostInAGap) {
  bench_nodes::HeartbeatCheck check;
  EXPECT_TRUE(std::holds_alternative<bench_nodes::InOrder>(check.observe(4)));
  const bench_nodes::Arrival arrival = check.observe(7);
  ASSERT_TRUE(std::holds_alternative<bench_nodes::Gap>(arrival));
  EXPECT_EQ(std::get<bench_nodes::Gap>(arrival).lost, 2);
}

#include <chrono>
#include <memory>

#include <gtest/gtest.h>
#include <rclcpp/rclcpp.hpp>

#include "bench_nodes/heartbeat.hpp"
#include "bench_nodes/monitor.hpp"

class Exchange : public testing::Test {
 protected:
  static void SetUpTestSuite() { rclcpp::init(0, nullptr); }
  static void TearDownTestSuite() { rclcpp::shutdown(); }
};

TEST_F(Exchange, MonitorHearsHeartbeat) {
  auto heartbeat = std::make_shared<bench_nodes::Heartbeat>();
  auto monitor = std::make_shared<bench_nodes::Monitor>();
  rclcpp::executors::SingleThreadedExecutor executor;
  executor.add_node(heartbeat);
  executor.add_node(monitor);

  const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(5);
  while (monitor->received() < 5 && std::chrono::steady_clock::now() < deadline) {
    executor.spin_once(std::chrono::milliseconds(100));
  }
  EXPECT_GE(monitor->received(), 5);
}
